    local table_insert = table.insert
    
    -- loadstringの隠蔽 (文字列結合で呼び出す)
    local env = (getgenv and getgenv()) or (getfenv and getfenv()) or _G
    local _ls = env["\108\111\97\100\115\116\114\105\110\103"] or loadstring

    while pc <= len do
        local op = byte(bytecode, pc)
        pc = pc + 1

        if op == OP_APPEND then
            -- [LEN] [KEY] [DATA...]
            local size = byte(bytecode, pc)
            pc = pc + 1
            local key = byte(bytecode, pc)
            pc = pc + 1
            
            local chunk = {}
            for i = 1, size do
                local b = byte(bytecode, pc)
                table_insert(chunk, char(bxor(b, key)))
                pc = pc + 1
            end
            table_insert(buffer, table.concat(chunk))
            
        elseif op == OP_EXEC then
            -- 実行命令: バッファを結合して実行
            local final_code = table.concat(buffer)
            local func, err = _ls(final_code)
            if func then
                return func(...)
            else
                warn("[Holon VM]: Execution Error")
            end
            break
        end
    end
end)(...)
